'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Send, Workflow } from 'lucide-react';

export default function ApplyODPage() {
    const [subjects, setSubjects] = useState<any[]>([]);
    const [form, setForm] = useState({ subject_id: '', date: '', reason: '', document_url: '' });
    const [myRequests, setMyRequests] = useState<any[]>([]);
    const [submitted, setSubmitted] = useState(false);

    useEffect(() => {
        loadRequests();
    }, []);

    const loadRequests = async () => {
        try {
            const res = await api.get<any[]>('/api/student/od/status');
            if (res.success) setMyRequests(res.data);
        } catch (e) { }
    };

    const handleSubmit = async () => {
        try {
            await api.post('/api/student/od/apply', form);
            setSubmitted(true);
            setForm({ subject_id: '', date: '', reason: '', document_url: '' });
            loadRequests();
            setTimeout(() => setSubmitted(false), 3000);
        } catch (e) { }
    };

    const statusColors: Record<string, string> = {
        pending_faculty: 'badge-warning',
        pending_hod: 'badge-info',
        approved: 'badge-success',
        rejected: 'badge-danger',
    };

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                Apply for OD
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Submit an On-Duty request for approval</p>

            <div className="card" style={{ padding: 28, marginBottom: 24 }}>
                <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 16 }}>New OD Request</h3>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                    <div className="form-group">
                        <label>Subject</label>
                        <input value={form.subject_id} onChange={(e) => setForm({ ...form, subject_id: e.target.value })} placeholder="Subject ID" />
                    </div>
                    <div className="form-group">
                        <label>Date</label>
                        <input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
                    </div>
                    <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                        <label>Reason</label>
                        <textarea value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })}
                            placeholder="Attending national-level hackathon..." rows={3}
                            style={{ width: '100%', padding: '10px 14px', border: '1px solid #e2e6ea', borderRadius: 8, fontSize: 14, fontFamily: 'Inter' }}
                        />
                    </div>
                    <div className="form-group">
                        <label>Document URL (Optional)</label>
                        <input value={form.document_url} onChange={(e) => setForm({ ...form, document_url: e.target.value })} placeholder="https://..." />
                    </div>
                </div>
                <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                    <button className="btn-primary" onClick={handleSubmit} disabled={!form.subject_id || !form.date || !form.reason}>
                        <Send size={16} /> Submit OD Request
                    </button>
                    {submitted && <span style={{ color: '#059669', fontSize: 14, fontWeight: 600 }}>✓ OD request submitted!</span>}
                </div>
            </div>

            <h3 style={{ fontSize: 18, fontWeight: 700, color: '#142B34', marginBottom: 16, fontFamily: 'Poppins' }}>
                My OD Requests
            </h3>
            <div className="table-container">
                <table>
                    <thead><tr><th>Date</th><th>Subject</th><th>Reason</th><th>Status</th></tr></thead>
                    <tbody>
                        {myRequests.length === 0 ? (
                            <tr><td colSpan={4} style={{ textAlign: 'center', padding: 32, color: '#8a9aa2' }}>No OD requests yet</td></tr>
                        ) : myRequests.map((r) => (
                            <tr key={r.id}>
                                <td>{r.date}</td>
                                <td>{r.subject_id}</td>
                                <td style={{ maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{r.reason}</td>
                                <td><span className={`badge ${statusColors[r.status] || 'badge-neutral'}`}>{r.status.replace('_', ' ')}</span></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
